    setLocations([]);
    setAssetRecords([]);
    setVendorRecords([]);
    setContactRecords([]);
    setServiceRecords([]);
    setProcedureRecords([]);
    setCalendarItems([]);
    setPartRecords([]);
    setPhotos([]);
    setIntakeDocs([]);
    setRequestRecords([]);

