  async function setupWeeklyOperations() {
    if (activePropertyId !== "2000" || weeklyOperationsSetupRunningRef.current || typeof window === "undefined") return;
    const setupKey = `atlas-weekly-operations-v3-${activePropertyId}`;
    if (window.localStorage.getItem(setupKey) === "ready") return;
    weeklyOperationsSetupRunningRef.current = true;
    try {
      const nextTasks = [...workPlanTasks];
      const nextTaskMeta = { ...taskMeta };
      const nextCalendar = [...calendarItems];
      const calendarRecords: AtlasCalendarItem[] = [];
      const weekdayDate = (weekday: string, weeksAhead = 0) => {
        const weekdays = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
        const target = weekdays.indexOf(weekday);
        const current = new Date(`${todayISO()}T12:00:00`).getDay();
        return addDays(todayISO(), ((target - current + 7) % 7) + weeksAhead * 7);
      };
      const routines = [
        { key: "monday-reset", day: "Monday", title: "Monday — Property Reset & Garage", minutes: 240, category: "House & Maintenance", notes: "Trash cans to street; weekend cleanup; interior/exterior walkthrough; owner requests; urgent and overdue work; geese and dog-area cleanup; scheduled vehicles; fuel/charging/tires/fluids/warning lights; clean the Golf Simulator Room and restock its refrigerator; deliveries; supplies; plan week; delegate appropriate work. Water pots and address dry spots." },
        { key: "tuesday-dock", day: "Tuesday", title: "Tuesday — Dock, Waterfront & Recreation", minutes: 210, category: "Dock & Waterfront", notes: "Clean dock and shoreline geese debris; clean and organize the dock storage box; inspect boards, cleats, bumpers, dock boxes and lighting; inspect Cobalt, Sea-Doo, lifts, covers and rollers; inspect sport court, trampoline and recreation equipment; clean BBQ. Water pots and address dry spots." },
        { key: "wednesday-landscape", day: "Wednesday", title: "Wednesday — Landscaping & Irrigation", minutes: 300, category: "Landscaping & Irrigation", notes: "Inspect lawns, beds, gardens, trees, pots and specialty plantings; review crew work; check irrigation zones, heads, pressure and dry spots; weed, prune and hand-water; inspect veggie boxes; photograph progress; record issues and create repair work orders when needed." },
        { key: "thursday-outdoor", day: "Thursday", title: "Thursday — Pool, Spa & Outdoor Cleaning", minutes: 180, category: "Pool & Spa", notes: "Complete linked Pool & Spa treatment and cleaning tasks; inspect equipment and fountain; clean patio furniture, covers, outdoor heaters, BBQ exterior and skylights; complete the scheduled window zone; finish vehicle cleaning when needed; water pots and address dry spots." },
        { key: "friday-ready", day: "Friday", title: "Friday — Maintenance & Weekend Readiness", minutes: 300, category: "House & Maintenance", notes: "Mow and edge; inspect boilers, pumps, HVAC, mechanical rooms, leaks, alarms, temperatures and unusual noises; test important lights, doors, gates and appliances; follow up vendors; update tasks, work orders, projects, photos and service history; review bottled water, toilet paper, paper towels, cleaning supplies, tools and maintenance materials, then complete a Home Depot supply run when needed; final walkthrough; prepare weekend and next week; review owner update." },
        { key: "friday-spiders", day: "Friday", title: "Friday — Seasonal Spider Control", minutes: 75, category: "House & Maintenance", notes: "April through October: remove webs; inspect exterior walls, eaves, doors, windows, garages, dock structures and outdoor furniture; treat recurring problem areas when appropriate." },
        { key: "monday-admin", day: "Monday", title: "Monday — Computer Work & Admin", minutes: 45, category: "Administration", notes: "Review email and messages; process pending Ramp expenses and receipts; review Meter Viewer invoices awaiting approval; update Atlas tasks, work orders, calendar and vendor follow-ups; identify administrative items that need action this week." },
        { key: "tuesday-admin", day: "Tuesday", title: "Tuesday — Computer Work & Admin", minutes: 45, category: "Administration", notes: "Review email and messages; process pending Ramp expenses and receipts; review Meter Viewer invoices awaiting approval; update Atlas with meeting decisions, vendor updates, photos, documents and new follow-up work." },
        { key: "wednesday-admin", day: "Wednesday", title: "Wednesday — Computer Work & Admin", minutes: 45, category: "Administration", notes: "Review email and messages; process pending Ramp expenses and receipts; review Meter Viewer invoices awaiting approval; update project, landscaping, irrigation, invoice and vendor records in Atlas." },
        { key: "thursday-admin", day: "Thursday", title: "Thursday — Computer Work & Admin", minutes: 45, category: "Administration", notes: "Review email and messages; process pending Ramp expenses and receipts; review Meter Viewer invoices awaiting approval; update completed work, service history, photos, documents and Friday follow-ups in Atlas." },
        { key: "friday-admin", day: "Friday", title: "Friday — Computer Work & Weekly Closeout", minutes: 60, category: "Administration", notes: "Clear priority email; finish pending Ramp expenses and receipts; complete Meter Viewer invoice review and approvals; update Atlas records; reconcile open follow-ups; prepare the weekly owner update and next week's administrative priorities." },
      ];
      const windowZones = [
        { key: "windows-waterside", title: "Clean windows — Waterside & Great Room", notes: "Waterside elevation, Great Room glass and adjacent exterior doors. Add notes and photos for access or condition issues." },
        { key: "windows-east", title: "Clean windows — East Side & Bedrooms", notes: "East elevation and bedroom windows. Record screens, damage or access issues." },
        { key: "windows-courtyard", title: "Clean windows — Courtyard & Main Entry", notes: "Courtyard, covered walkway, entrance and nearby glass." },
        { key: "windows-garage", title: "Clean windows — Garages, ADU & Remaining Areas", notes: "Garage, ADU and remaining scheduled windows. Record completion notes and photos." },
      ];
      for (const [index, definition] of [...routines, ...windowZones.map((zone, zoneIndex) => ({ ...zone, day: "Thursday", minutes: 90, category: "House & Maintenance", weeksAhead: zoneIndex }))].entries()) {
        const isWindow = index >= routines.length;
        let task = nextTasks.find((item) => normalizeLocationName(item.title) === normalizeLocationName(definition.title));
        if (!task) {
          task = { id: uid("routine-task"), title: definition.title, minutes: definition.minutes, priority: "Medium", category: definition.category, locationId: "general", preferredDay: definition.day as WorkPlanDay, locked: false, recurring: true, fixedTime: "", notes: definition.notes };
          nextTasks.push(task);
        } else {
          const taskIndex = nextTasks.findIndex((item) => item.id === task!.id);
          nextTasks[taskIndex] = { ...task, minutes: definition.minutes, category: definition.category, preferredDay: definition.day as WorkPlanDay, recurring: true, notes: definition.notes };
          task = nextTasks[taskIndex];
        }
        const meta = taskDetails(task.id);
        const dueDate = meta.dueDate || weekdayDate(definition.day, "weeksAhead" in definition ? Number(definition.weeksAhead) : 0);
        nextTaskMeta[task.id] = { ...meta, status: meta.status === "Completed" ? "Open" : meta.status, dueDate, assignee: meta.assignee || "Nick", createdAt: meta.createdAt || new Date().toISOString(), recurrenceInterval: isWindow ? 4 : 1, recurrenceUnit: "Weeks", recurrenceEndDate: definition.key === "friday-spiders" ? `${new Date().getFullYear()}-10-31` : "", season: definition.key === "friday-spiders" ? "Summer" : "Year-Round", skippable: true, flexibleTime: true, notes: definition.notes, updatedAt: new Date().toISOString() };
        calendarRecords.push(normalizeCalendar({ id: `routine-${definition.key}`, propertyId: activePropertyId, date: dueDate, title: definition.title, area: definition.category, categoryLabel: "Routine", allDay: true, repeat: isWindow ? "Custom" : "Weekly", reminder: "Morning of", notes: definition.notes, linkedType: "Task", linkedId: task.id, linkedName: task.title, source: "task", status: "Scheduled" }));
      }
      calendarRecords.push(
        normalizeCalendar({ id: "weekly-property-meeting", propertyId: activePropertyId, date: weekdayDate("Tuesday"), time: "10:00", title: "Weekly Property Meeting", area: "House & Maintenance", categoryLabel: "Meeting", allDay: false, repeat: "Weekly", reminder: "Morning of", notes: "Nick, Steve, Summer and Pat.", linkedType: "None", linkedId: "", linkedName: "", source: "manual", status: "Scheduled" }),
        normalizeCalendar({ id: "lanken-tuesday-crew", propertyId: activePropertyId, date: weekdayDate("Tuesday"), title: "Lanken Landscaping Crew", area: "Landscaping & Irrigation", categoryLabel: "Crew Visit", allDay: true, repeat: "Weekly", reminder: "Day before", notes: "Half-day Tuesday visit coordinated by Pat. Record planned work, areas, before/after photos, completed and unfinished work, and follow-up. Current progress: waterside bed grass removed and cleaned; mulching underway; work quality excellent.", linkedType: "None", linkedId: "", linkedName: "", source: "manual", status: "Scheduled" }),
        normalizeCalendar({ id: "nick-steve-friday-meeting", propertyId: activePropertyId, date: weekdayDate("Friday"), time: "09:00", title: "Nick and Steve Meeting", area: "House & Maintenance", categoryLabel: "Meeting", allDay: false, repeat: "Weekly", reminder: "Morning of", notes: "Weekly Friday operations meeting.", linkedType: "None", linkedId: "", linkedName: "", source: "manual", status: "Scheduled" }),
        normalizeCalendar({ id: "weekly-owner-update", propertyId: activePropertyId, date: weekdayDate("Friday"), time: "15:30", title: "Review Weekly Owner Update", area: "House & Maintenance", categoryLabel: "Owner Update", allDay: false, repeat: "Weekly", reminder: "Morning of", notes: "Atlas prepares the draft after the final walkthrough. Review, edit and approve before sending.", linkedType: "None", linkedId: "", linkedName: "", source: "manual", status: "Scheduled" }),
      );
      for (const record of calendarRecords) {
        const recordIndex = nextCalendar.findIndex((item) => item.id === record.id);
        if (recordIndex >= 0) nextCalendar[recordIndex] = record;
        else nextCalendar.push(record);
      }
      setWorkPlanTasks(nextTasks);
      setTaskMeta(nextTaskMeta);
      setCalendarItems(byTitle(nextCalendar));
      saveStoredArray(storageKeys.calendar[0], byTitle(nextCalendar));
      const results = await Promise.all(calendarRecords.map((record) => postAtlasRecord("calendar", record)));
      if (results.some((saved) => !saved)) throw new Error("Some routine calendar records did not sync.");
      window.localStorage.setItem(setupKey, "ready");
      showSaveToast("Weekly operations routines are ready.");
    } catch (error) {
      console.error("Atlas weekly operations setup failed", error);
      showSaveToast("Weekly operations setup will retry.", "warning");
    } finally {
      weeklyOperationsSetupRunningRef.current = false;
    }
  }

  function createSeasonalTask(item: AtlasSeasonalItem) {
    const task: WorkPlanTask = { id: uid("plan-task"), title: item.title, minutes: 60, priority: "Medium", category: "Maintenance", locationId: "general", preferredDay: "Auto", locked: false, recurring: item.frequency !== "One-time", fixedTime: "", notes: item.notes };
    setWorkPlanTasks((current) => [task, ...current]);
    setTaskMeta((current) => ({ ...current, [task.id]: { status: "Open", dueDate: item.targetDate || item.deadline, assignee: item.assignedTo === "Addison" ? "Addison" : item.assignedTo === "Nick" ? "Nick" : "Unassigned", createdAt: new Date().toISOString(), notes: item.notes } }));
    setSeasonalItems((current) => current.map((entry) => entry.id === item.id ? { ...entry, status: "Scheduled" } : entry));
    setSelectedTaskId(task.id);
    setTasksView("tasks");
    showSaveToast("Seasonal work added to Tasks.");
  }

  function applyOperationsTemplate(template: AtlasOperationsTemplate) {
    const targetDate = templateDates[template.id] || addDays(todayISO(), 7);
    const projectId = template.createsProject ? uid("project") : "";
    const createdAt = new Date().toISOString();
    const tasks = template.items.map((item) => ({
      id: uid("plan-task"),
      title: item.title,
      minutes: item.minutes,
      priority: item.priority,
      category: item.category,
      locationId: "general",
      preferredDay: "Auto",
      locked: false,
      recurring: false,
      fixedTime: "",
      notes: `Created from ${template.title}.`,
    } satisfies WorkPlanTask));

    setWorkPlanTasks((current) => [...tasks, ...current]);
    setTaskMeta((current) => {
      const next = { ...current };
      tasks.forEach((task, index) => {
        const item = template.items[index];
        next[task.id] = {
          status: "Open",
          dueDate: addDays(targetDate, -item.daysBefore),
          assignee: item.assignedTo || (item.addisonReady ? "Addison" : "Nick"),
          createdAt,
          projectId: projectId || undefined,
          notes: `Created from ${template.title}.`,
        };
      });
      return next;
    });

    if (template.createsProject) {
      const project: PhotoTimelineProject = {
        id: projectId,
        title: template.title,
        category: template.category,
        scale: template.items.length >= 7 ? "Major" : "Standard",
        status: "Planning",
        assetId: "",
        locationId: "",
        vendorId: "",
        workOrderId: "",
        workOrderIds: [],
        vendorIds: [],
        documentIds: [],
        assigneeIds: [],
        notes: `${template.detail} Target date: ${formatDate(targetDate)}.`,
        coverPhotoId: "",
        createdAt,
        progress: 0,
        phase: "Planning",
        startDate: todayISO(),
      };
      setPhotoTimelineProjects((current) => [project, ...current]);
    }

    setSelectedTaskId(tasks[0]?.id || "");
    setTasksView("tasks");
    showSaveToast(`${template.title} created with ${tasks.length} task${tasks.length === 1 ? "" : "s"}.`);
  }

  function makeSuggestedTaskRepeating(task: WorkPlanTask) {
    const nextDue = addDays(todayISO(), 7);
    const weekdayLabel = new Date().toLocaleDateString(undefined, {
      weekday: "long",
    });
    const preferredDay: WorkPlanDay | "Auto" = workPlanDays.includes(
      weekdayLabel as WorkPlanDay,
    )
      ? (weekdayLabel as WorkPlanDay)
      : "Auto";

    setWorkPlanTasks((current) =>
      current.map((item) =>
        item.id === task.id
          ? { ...item, recurring: true, preferredDay }
          : item,
      ),
    );
    updateTaskDetails(task.id, {
      status: "Open",
      dueDate: nextDue,
      completedAt: undefined,
    });
    showSaveToast("Task marked as repeating and returned next week.");
  }

  function renderOperationsTemplates() {
    return <div style={{ display: "grid", gap: 12 }}>
      <div style={noticeStyle}>Templates create a temporary, organized plan only when you approve it. They do not add permanent routines or clutter Atlas automatically.</div>
      <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "repeat(2,minmax(0,1fr))", gap: 10 }}>
        {atlasOperationsTemplates.filter((template) => template.id !== "graduation-party").map((template) => <div key={template.id} style={cardStyle}>
          <div style={{ display: "flex", justifyContent: "space-between", gap: 8, alignItems: "flex-start" }}><div><strong style={{ color: colors.navy3 }}>{template.title}</strong><small style={{ ...mutedSmallStyle, display: "block", marginTop: 5 }}>{template.detail}</small></div><span style={badgeStyle(template.createsProject ? "Scheduled" : "Monitor")}>{template.createsProject ? "Project + tasks" : "Tasks"}</span></div>
          <div style={{ marginTop: 10 }}><Field label="Event or target date" type="date" value={templateDates[template.id] || addDays(todayISO(), 7)} onChange={(value) => setTemplateDates((current) => ({ ...current, [template.id]: value }))}/></div>
          <div style={{ marginTop: 9, padding: "8px 10px", border: `1px solid ${colors.line}`, borderRadius: 10, background: "#F8FAFC" }}><small style={mutedSmallStyle}>{template.items.length} suggested actions · {template.items.filter((item) => item.addisonReady).length} automatically assigned to Addison</small></div>
          <button type="button" onClick={() => applyOperationsTemplate(template)} style={{ ...goldButtonStyle, marginTop: 10 }}>Create Plan</button>
        </div>)}
      </div>
    </div>;
  }

  function ensureGraduationPartyChecklist() {
    // Graduation Party is now fully user-controlled.
    // Atlas must never recreate this list or its items during load, refresh,
    // deployment, property switching, or opening the Lists screen.
    if (typeof window !== "undefined") {
      window.localStorage.setItem(
        `atlas-graduation-party-list-initialized-v2-${activePropertyId}`,
        "ready",
      );
    }
  }

  function restoreGraduationPartyStandardItems() {
    const template = atlasOperationsTemplates.find((item) => item.id === "graduation-party");
    if (!template) return;
    const existingTitles = new Set(
      checklistItems("graduation-party").map((task) =>
        task.title.trim().toLowerCase(),
      ),
    );
    const missing = template.items.filter(
      (item) => !existingTitles.has(item.title.trim().toLowerCase()),
    );
    if (!missing.length) {
      showSaveToast("All standard Graduation Party items are already present.");
      return;
    }

    const createdAt = new Date().toISOString();
    const tasks = missing.map((item) => ({
      id: `grad-party-${slugify(item.title)}`,
      title: item.title,
      minutes: item.minutes,
      priority: item.priority,
      category: "Graduation Party Checklist",
      locationId: "general",
      preferredDay: "Auto" as const,
      locked: false,
      recurring: false,
      fixedTime: "",
      notes: "Graduation Party Checklist",
    } satisfies WorkPlanTask));

    setWorkPlanTasks((current) => {
      const existingIds = new Set(current.map((task) => String(task.id)));
      const existingPartyTitles = new Set(
        current
          .filter(
            (task) =>
              task.category === "Graduation Party Checklist" ||
              taskDetails(task.id).listId === "graduation-party",
          )
          .map((task) => task.title.trim().toLowerCase().replace(/\s+/g, " ")),
      );
      const safeToAdd = tasks.filter(
        (task) =>
          !existingIds.has(String(task.id)) &&
          !existingPartyTitles.has(
            task.title.trim().toLowerCase().replace(/\s+/g, " "),
          ),
      );
      return safeToAdd.length ? [...current, ...safeToAdd] : current;
    });
    setTaskMeta((current) => {
      const next = { ...current };
      tasks.forEach((task, index) => {
        const item = missing[index];
        next[task.id] = {
          status: "Open",
          dueDate: "",
          assignee: item.assignedTo || (item.addisonReady ? "Addison" : "Nick"),
          createdAt,
          completionHistory: [],
          flexibleTime: true,
          skippable: true,
          listId: "graduation-party",
          listName: "Graduation Party",
          dashboardListPinned: false,
        };
      });
      return next;
    });
    showSaveToast(`Restored ${missing.length} standard Graduation Party item${missing.length === 1 ? "" : "s"}.`);
  }

  function openGraduationPartyChecklist() {
    const partyExists = checklistDefinitions().some(
      (definition) => definition.id === "graduation-party",
    );
    if (partyExists) {
      setSelectedListId("graduation-party");
    }
    setTasksView("lists");
  }

  const collaborativeDepartments = [
    { id: "house", label: "House / Interior" },
    { id: "garage", label: "Garage" },
    { id: "pool", label: "Pool & Spa" },
    { id: "landscaping", label: "Landscaping & Irrigation" },
    { id: "marine", label: "Dock & Waterfront" },
  ] as const;

  function teamMemberKey(member: { id?: string; email?: string; name?: string }) {
    return String(member.id || member.email || member.name || "").trim();
  }

  function listMetaValue<T>(listId: string, field: string, fallback: T): T {
    const records = workPlanTasks.filter(
      (task) =>
        taskDetails(task.id).listId === listId ||
        (listId === "graduation-party" &&
          task.category === "Graduation Party Checklist"),
    );
    for (const record of records) {
      const meta = taskDetails(record.id) as any;
      if (meta[field] !== undefined) return meta[field] as T;
    }
    return fallback;
  }

  function updateCollaborativeListMeta(
    listId: string,
    listName: string,
    patch: Record<string, unknown>,
  ) {
    const records = workPlanTasks.filter(
      (task) =>
        taskDetails(task.id).listId === listId ||
        (listId === "graduation-party" &&
          task.category === "Graduation Party Checklist"),
    );
    const ids = new Set(records.map((record) => String(record.id)));
    const updatedAt = new Date().toISOString();

    setTaskMeta((current) => {
      const next = { ...current } as Record<string, AtlasTaskMeta>;
      ids.forEach((id) => {
        next[id] = {
          ...(current[id] || taskDetails(id)),
          listId,
          listName,
          ...patch,
          updatedAt,
        } as AtlasTaskMeta;
      });
      try {
        window.localStorage.setItem(
          `atlas-task-meta-v1-${activePropertyId}`,
          JSON.stringify(next),
        );
        if (activePropertyId === "2000") {
          window.localStorage.setItem("atlas-task-meta-v1", JSON.stringify(next));
        }
      } catch {}
      return next;
    });

    records.forEach((record) => {
      const meta = taskDetails(record.id) as any;
      void postAtlasRecord("tasks" as AtlasTable, {
        ...record,
        ...meta,
        listId,
        listName,
        ...patch,
        taskMeta: {
          ...meta,
          listId,
          listName,
          ...patch,
          updatedAt,
        },
        propertyId: activePropertyId,
        updatedAt,
      });
    });
  }

  function listMemberLabel(memberId: string) {
    const member = teamDirectory.find(
      (entry) =>
        teamMemberKey(entry) === memberId ||
        entry.email === memberId,
    );
    return member?.name || memberId;
  }

  function setChecklistTaskAssignees(
    task: WorkPlanTask,
    assigneeIds: string[],
    departmentIds?: string[],
  ) {
    const uniqueAssignees = Array.from(new Set(assigneeIds.filter(Boolean)));
    const uniqueDepartments = Array.from(
      new Set((departmentIds || []).filter(Boolean)),
    );
    const firstMember = teamDirectory.find(
      (entry) => teamMemberKey(entry) === uniqueAssignees[0],
    );
    const compatibilityAssignee =
      uniqueAssignees.length === 1
        ? firstMember?.name || "Other"
        : uniqueAssignees.length > 1
          ? "Other"
          : "Unassigned";

    updateTaskDetails(
      task.id,
      {
        assignee: compatibilityAssignee as any,
        assigneeIds: uniqueAssignees,
        departmentIds: uniqueDepartments,
      } as any,
    );
  }

  function checklistDefinitions() {
    const custom = workPlanTasks
      .filter((task) => task.category === "Atlas List Definition")
      .map((task) => ({
        id: taskDetails(task.id).listId || task.id,
        name: taskDetails(task.id).listName || task.title,
      }));
    const graduationRecords = workPlanTasks.filter(
      (task) =>
        taskDetails(task.id).listId === "graduation-party" ||
        task.category === "Graduation Party Checklist",
    );
    const graduation = graduationRecords.length
      ? [{
          id: "graduation-party",
          name:
            graduationRecords
              .map((task) => taskDetails(task.id).listName || "")
              .find(Boolean) || "Graduation Party",
        }]
      : [];
    return [
      ...graduation,
      ...custom.filter(
        (item, index, all) =>
          item.id !== "graduation-party" &&
          all.findIndex((candidate) => candidate.id === item.id) === index,
      ),
    ];
  }

  function checklistItems(listId: string) {
    return workPlanTasks.filter((task) => task.category !== "Atlas List Definition" && (taskDetails(task.id).listId === listId || (listId === "graduation-party" && task.category === "Graduation Party Checklist")));
  }

  function createChecklist() {
    const name = window.prompt("Name this checklist:", "")?.trim();
    if (!name) return;
    const listId = `list-${slugify(name)}-${Date.now()}`;
    const marker: WorkPlanTask = { id: `atlas-list-definition-${listId}`, title: name, minutes: 5, priority: "Low", category: "Atlas List Definition", locationId: "general", preferredDay: "Auto", locked: true, recurring: false, fixedTime: "", notes: "Atlas checklist definition" };
    setWorkPlanTasks((current) => [...current, marker]);
    const creatorMemberId =
      teamDirectory.find(
        (member) =>
          member.email &&
          member.email === String(currentAtlasUser?.email || "").toLowerCase(),
      )?.id ||
      String(currentAtlasUser?.id || "");
    setTaskMeta((current) => ({
      ...current,
      [marker.id]: {
        status: "Open",
        dueDate: "",
        assignee: "Nick",
        createdAt: new Date().toISOString(),
        completionHistory: [],
        flexibleTime: true,
        skippable: true,
        listId,
        listName: name,
        dashboardListPinned: false,
        listLeadId: creatorMemberId,
        listMemberIds: creatorMemberId ? [creatorMemberId] : [],
        listDepartmentIds: [],
      } as any,
    }));
    setSelectedListId(listId);
    setTasksView("lists");
    showSaveToast(`${name} list created.`);
  }

  function renameChecklist(listId: string, currentName: string) {
    const nextName = window.prompt("Rename this list:", currentName)?.trim();
    if (!nextName || nextName === currentName) return;
    const recordIds = new Set<string>(
      workPlanTasks
        .filter((task) => taskDetails(task.id).listId === listId || (listId === "graduation-party" && task.category === "Graduation Party Checklist"))
        .map((task) => String(task.id)),
    );
    setWorkPlanTasks((current) =>
      current.map((task) =>
        recordIds.has(task.id) && task.category === "Atlas List Definition"
          ? { ...task, title: nextName }
          : task,
      ),
    );
    setTaskMeta((current) => {
      const next = { ...current };
      recordIds.forEach((id) => {
        next[id] = {
          ...taskDetails(id),
          listId,
          listName: nextName,
          updatedAt: new Date().toISOString(),
        };
      });
      return next;
    });
    recordIds.forEach((id) => {
      const task = workPlanTasks.find((item) => item.id === id);
      if (!task) return;
      const meta = taskDetails(id);
      void postAtlasRecord("tasks" as AtlasTable, {
        ...task,
        ...meta,
        title: task.category === "Atlas List Definition" ? nextName : task.title,
        listId,
        listName: nextName,
        taskMeta: { ...meta, listId, listName: nextName },
        propertyId: activePropertyId,
        updatedAt: new Date().toISOString(),
      });
    });
    showSaveToast(`List renamed to ${nextName}.`);
  }

  function deleteChecklist(listId: string, listName: string) {
    const records = workPlanTasks.filter(
      (task) =>
        taskDetails(task.id).listId === listId ||
        (listId === "graduation-party" && task.category === "Graduation Party Checklist"),
    );
    if (!records.length) return;
    if (!window.confirm(`Delete "${listName}" and all ${records.length} item${records.length === 1 ? "" : "s"}?`)) return;

    const ids = new Set<string>(records.map((task) => String(task.id)));
    const nextTasks = workPlanTasks.filter((task) => !ids.has(task.id));
    const nextMeta = { ...taskMeta };
    ids.forEach((id) => delete nextMeta[id]);

    setWorkPlanTasks(nextTasks);
    setTaskMeta(nextMeta);
    saveStoredArray(`atlas-tasks-v1-${activePropertyId}`, nextTasks);
    if (activePropertyId === "2000") saveStoredArray("atlas-tasks-v1", nextTasks);
    try {
      window.localStorage.setItem(`atlas-task-meta-v1-${activePropertyId}`, JSON.stringify(nextMeta));
      if (activePropertyId === "2000") window.localStorage.setItem("atlas-task-meta-v1", JSON.stringify(nextMeta));
      if (listId === "graduation-party") {
        window.localStorage.setItem(
          `atlas-graduation-party-list-initialized-v2-${activePropertyId}`,
          "ready",
        );
        window.localStorage.setItem(
          `atlas-graduation-party-user-deleted-v1-${activePropertyId}`,
          "true",
        );
        window.localStorage.setItem(
          `atlas-graduation-party-dedupe-v1-${activePropertyId}`,
          "ready",
        );
      }
    } catch {}

    ids.forEach((id) => void deleteOperationalRecord("tasks" as AtlasTable, id));

    const remainingDefinitions = checklistDefinitions().filter((definition) => definition.id !== listId);
    setSelectedListId(remainingDefinitions[0]?.id || "");
    showSaveToast(`${listName} deleted.`);
  }

  function editChecklistItem(task: WorkPlanTask) {
    const title = window.prompt("Edit checklist item:", task.title)?.trim();
    if (!title || title === task.title) return;
    const updatedAt = new Date().toISOString();
    const updatedTask = { ...task, title };
    const meta = taskDetails(task.id);
    setWorkPlanTasks((current) => current.map((item) => item.id === task.id ? updatedTask : item));
    updateTaskDetails(task.id, { updatedAt });
    void postAtlasRecord("tasks" as AtlasTable, {
      ...updatedTask,
      ...meta,
      taskMeta: { ...meta, updatedAt },
      propertyId: activePropertyId,
      updatedAt,
    });
    showSaveToast("Checklist item updated.");
  }

  function keepChecklistItemAsWeeklyTask(task: WorkPlanTask) {
    const meta = taskDetails(task.id) as any;
    const updatedAt = new Date().toISOString();
    const nextTask: WorkPlanTask = {
      ...task,
      category:
        task.category === "Graduation Party Checklist" ||
        task.category === "Atlas Checklist Item"
          ? "General"
          : task.category,
      recurring: true,
      notes:
        task.notes === "Graduation Party Checklist" ||
        / checklist$/i.test(String(task.notes || ""))
          ? ""
          : task.notes,
    };

    const nextMeta = {
      ...meta,
      status: "Open",
      dueDate: meta.dueDate || todayISO(),
      recurrenceInterval: 1,
      recurrenceUnit: "Weeks",
      recurrenceEndDate: "",
      listId: undefined,
      listName: undefined,
      dashboardListPinned: false,
      listNotes: undefined,
      listLeadId: undefined,
      listMemberIds: undefined,
      listDepartmentIds: undefined,
      completedAt: undefined,
      updatedAt,
    };

    setWorkPlanTasks((current) =>
      current.map((item) => (item.id === task.id ? nextTask : item)),
    );
    setTaskMeta((current) => ({
      ...current,
      [task.id]: nextMeta,
    }));

    void postAtlasRecord("tasks" as AtlasTable, {
      ...nextTask,
      ...nextMeta,
      taskMeta: nextMeta,
      propertyId: activePropertyId,
      updatedAt,
    });

    showSaveToast(`${task.title} is now a weekly Task.`);
  }

  function removeChecklistDuplicates(listId: string) {
    const items = checklistItems(listId);
    const groups = new Map<string, WorkPlanTask[]>();

    items.forEach((task) => {
      const key = task.title.trim().toLowerCase().replace(/\s+/g, " ");
      groups.set(key, [...(groups.get(key) || []), task]);
    });

    const duplicateIds = new Set<string>();
    for (const group of groups.values()) {
      if (group.length < 2) continue;
      const ranked = [...group].sort((a, b) => {
        const aMeta = taskDetails(a.id);
        const bMeta = taskDetails(b.id);
        const aCompleted = aMeta.status === "Completed" ? 1 : 0;
        const bCompleted = bMeta.status === "Completed" ? 1 : 0;
        if (aCompleted !== bCompleted) return bCompleted - aCompleted;
        return String(bMeta.updatedAt || bMeta.createdAt || "").localeCompare(
          String(aMeta.updatedAt || aMeta.createdAt || ""),
        );
      });
      ranked.slice(1).forEach((task) => duplicateIds.add(String(task.id)));
    }

    if (!duplicateIds.size) {
      showSaveToast("No duplicate items found.");
      return;
    }

    const nextTasks = workPlanTasks.filter((task) => !duplicateIds.has(String(task.id)));
    const nextMeta = { ...taskMeta };
    duplicateIds.forEach((id) => delete nextMeta[id]);

    setWorkPlanTasks(nextTasks);
    setTaskMeta(nextMeta);
    saveStoredArray(`atlas-tasks-v1-${activePropertyId}`, nextTasks);
    if (activePropertyId === "2000") saveStoredArray("atlas-tasks-v1", nextTasks);

    try {
      window.localStorage.setItem(`atlas-task-meta-v1-${activePropertyId}`, JSON.stringify(nextMeta));
      if (activePropertyId === "2000") {
        window.localStorage.setItem("atlas-task-meta-v1", JSON.stringify(nextMeta));
      }
    } catch {}

    duplicateIds.forEach((id) => void deleteOperationalRecord("tasks" as AtlasTable, id));
    showSaveToast(`Removed ${duplicateIds.size} duplicate item${duplicateIds.size === 1 ? "" : "s"}.`);
  }

  function deleteCompletedChecklistItems(listId: string, listName: string) {
    const completedItems = checklistItems(listId).filter(
      (task) => taskDetails(task.id).status === "Completed",
    );

    if (!completedItems.length) {
      showSaveToast("No completed items to remove.");
      return;
    }

    if (!window.confirm(
      `Delete ${completedItems.length} completed item${completedItems.length === 1 ? "" : "s"} from "${listName}"?`,
    )) return;

    const ids = new Set<string>(completedItems.map((task) => String(task.id)));
    const nextTasks = workPlanTasks.filter((task) => !ids.has(String(task.id)));
    const nextMeta = { ...taskMeta };
    ids.forEach((id) => delete nextMeta[id]);

    setWorkPlanTasks(nextTasks);
    setTaskMeta(nextMeta);
    saveStoredArray(`atlas-tasks-v1-${activePropertyId}`, nextTasks);
    if (activePropertyId === "2000") saveStoredArray("atlas-tasks-v1", nextTasks);

    try {
      window.localStorage.setItem(`atlas-task-meta-v1-${activePropertyId}`, JSON.stringify(nextMeta));
      if (activePropertyId === "2000") {
        window.localStorage.setItem("atlas-task-meta-v1", JSON.stringify(nextMeta));
      }
    } catch {}

    ids.forEach((id) => void deleteOperationalRecord("tasks" as AtlasTable, id));
    showSaveToast(`Deleted ${ids.size} completed item${ids.size === 1 ? "" : "s"}.`);
  }

  function addGraduationPartyChecklistItem() {
    const title = newPartyChecklistItem.trim();
    if (!title) return;
    const definition = checklistDefinitions().find((item) => item.id === selectedListId) || { id: "graduation-party", name: "Graduation Party" };
    const dashboardListPinned = workPlanTasks.some((item) => taskDetails(item.id).listId === definition.id && taskDetails(item.id).dashboardListPinned);
    const task: WorkPlanTask = { id: uid("checklist-item"), title, minutes: 30, priority: "Medium", category: definition.id === "graduation-party" ? "Graduation Party Checklist" : "Atlas Checklist Item", locationId: "general", preferredDay: "Auto", locked: false, recurring: false, fixedTime: "", notes: `${definition.name} Checklist` };
    setWorkPlanTasks((current) => [...current, task]);
    const inheritedMemberIds = listMetaValue<string[]>(
      definition.id,
      "listMemberIds",
      [],
    );
    const inheritedDepartmentIds = listMetaValue<string[]>(
      definition.id,
      "listDepartmentIds",
      [],
    );
    const inheritedLeadId = listMetaValue<string>(
      definition.id,
      "listLeadId",
      "",
    );
    const defaultAssigneeId =
      inheritedLeadId || inheritedMemberIds[0] || "";
    const defaultAssigneeName =
      listMemberLabel(defaultAssigneeId) || "Unassigned";
    setTaskMeta((current) => ({
      ...current,
      [task.id]: {
        status: "Open",
        dueDate: "",
        assignee: defaultAssigneeId ? defaultAssigneeName : "Unassigned",
        assigneeIds: defaultAssigneeId ? [defaultAssigneeId] : [],
        departmentIds: inheritedDepartmentIds,
        createdAt: new Date().toISOString(),
        completionHistory: [],
        flexibleTime: true,
        skippable: true,
        listId: definition.id,
        listName: definition.name,
        dashboardListPinned,
        listLeadId: inheritedLeadId,
        listMemberIds: inheritedMemberIds,
        listDepartmentIds: inheritedDepartmentIds,
      } as any,
    }));
    setNewPartyChecklistItem("");
    showSaveToast("Checklist item added.");
  }

  function renderGraduationPartyChecklist() {
    const definitions = checklistDefinitions();
    const selectedDefinition =
      definitions.find((item) => item.id === selectedListId) ||
      definitions[0] ||
      { id: "", name: "Lists" };
    const items = selectedDefinition.id ? checklistItems(selectedDefinition.id) : [];
    const completed = items.filter((task) => taskDetails(task.id).status === "Completed").length;
    const listRecords = selectedDefinition.id
      ? workPlanTasks.filter((task) => taskDetails(task.id).listId === selectedDefinition.id || (selectedDefinition.id === "graduation-party" && task.category === "Graduation Party Checklist"))
      : [];
    const pinned = listRecords.some((task) => taskDetails(task.id).dashboardListPinned);
    const listDefinitionRecord = listRecords.find(
      (task) => task.category === "Atlas List Definition",
    );
    const listNotes = listDefinitionRecord
      ? String((taskDetails(listDefinitionRecord.id) as any).listNotes ?? "")
      : String(
          listRecords
            .slice()
            .sort((a, b) =>
              String((taskDetails(b.id) as any).updatedAt || "").localeCompare(
                String((taskDetails(a.id) as any).updatedAt || ""),
              ),
            )
            .map((task) => (taskDetails(task.id) as any).listNotes)
            .find((value) => value !== undefined) ?? "",
        );
    const listLeadId = listMetaValue<string>(
      selectedDefinition.id,
      "listLeadId",
      "",
    );
    const listMemberIds = listMetaValue<string[]>(
      selectedDefinition.id,
      "listMemberIds",
      [],
    );
    const listDepartmentIds = listMetaValue<string[]>(
      selectedDefinition.id,
      "listDepartmentIds",
      [],
    );
    const propertyTeamMembers = teamDirectory.filter(
      (member) =>
        member.active !== false &&
        (!member.propertyIds.length ||
          member.propertyIds.includes(activePropertyId) ||
          ["master", "administrator"].includes(member.role)),
    );
    const setDashboardPinned = (nextPinned: boolean) => {
      updateCollaborativeListMeta(
        selectedDefinition.id,
        selectedDefinition.name,
        { dashboardListPinned: nextPinned },
      );
      showSaveToast(nextPinned ? `${selectedDefinition.name} added to Dashboard.` : `${selectedDefinition.name} removed from Dashboard.`);
    };
    const updateListNotes = (value: string) => {
      updateCollaborativeListMeta(
        selectedDefinition.id,
        selectedDefinition.name,
        { listNotes: value },
      );
    };
    return <div style={{ display: "grid", gap: 12 }}>
      <section style={{ ...cardStyle, padding: 14 }}>
        <div style={{ display: "flex", justifyContent: "space-between", gap: 10, alignItems: "center", flexWrap: "wrap" }}><div><div style={eyebrowStyle}>Reusable Checklists</div><h2 style={{ margin: "3px 0", color: colors.navy }}>Lists</h2></div><button type="button" onClick={createChecklist} style={goldButtonStyle}>+ New List</button></div>
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 10 }}>{definitions.map((definition) => <button key={definition.id} type="button" onClick={() => { setSelectedListId(definition.id); }} style={selectedDefinition.id === definition.id ? goldButtonStyle : secondaryButtonStyle}>{definition.name}</button>)}</div>
      </section>
      <section style={{ ...cardStyle, padding: 14 }}>
        <div style={{ display: "flex", justifyContent: "space-between", gap: 10, alignItems: "center", flexWrap: "wrap" }}><div><div style={eyebrowStyle}>Checklist</div><h2 style={{ margin: "3px 0", color: colors.navy }}>{selectedDefinition.name}</h2><small style={mutedSmallStyle}>{completed} of {items.length} complete</small></div><div style={{ display: "flex", gap: 7, flexWrap: "wrap" }}><button type="button" onClick={() => renameChecklist(selectedDefinition.id, selectedDefinition.name)} style={secondaryButtonStyle}>Rename</button><button type="button" onClick={() => setDashboardPinned(!pinned)} style={pinned ? goldButtonStyle : secondaryButtonStyle}>{pinned ? "Remove from Dashboard" : "Add to Dashboard"}</button><button type="button" onClick={() => removeChecklistDuplicates(selectedDefinition.id)} style={secondaryButtonStyle}>Remove Duplicates</button><button type="button" onClick={() => deleteCompletedChecklistItems(selectedDefinition.id, selectedDefinition.name)} style={secondaryButtonStyle}>Delete Completed</button><button type="button" onClick={() => deleteChecklist(selectedDefinition.id, selectedDefinition.name)} style={{ ...secondaryButtonStyle, color: colors.red, borderColor: "#FDA29B" }}>Delete List</button></div></div>
        <div style={{ display: "grid", gap: 10, marginTop: 12, padding: 11, border: `1px solid ${colors.line}`, borderRadius: 11, background: "#F8FAFC" }}>
          <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "minmax(180px, .7fr) minmax(0, 1.3fr)", gap: 10 }}>
            <label style={{ display: "grid", gap: 5 }}>
              <span style={fieldLabelStyle}>LEAD</span>
              <select
                value={listLeadId}
                onChange={(event) => {
                  const nextLeadId = event.currentTarget.value;
                  const nextMembers = nextLeadId
                    ? Array.from(new Set([...listMemberIds, nextLeadId]))
                    : listMemberIds;
                  updateCollaborativeListMeta(
                    selectedDefinition.id,
                    selectedDefinition.name,
                    { listLeadId: nextLeadId, listMemberIds: nextMembers },
                  );
                }}
                style={inputStyle}
              >
                <option value="">No lead</option>
                {propertyTeamMembers.map((member) => (
                  <option key={teamMemberKey(member)} value={teamMemberKey(member)}>
                    {member.name}
                  </option>
                ))}
              </select>
            </label>

            <div>
              <span style={fieldLabelStyle}>SHARED WITH</span>
              <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 5 }}>
                {propertyTeamMembers.map((member) => {
                  const memberId = teamMemberKey(member);
                  const active = listMemberIds.includes(memberId);
                  return (
                    <button
                      key={memberId}
                      type="button"
                      onClick={() => {
                        const nextMembers = active
                          ? listMemberIds.filter((id) => id !== memberId)
                          : [...listMemberIds, memberId];
                        const nextLead =
                          listLeadId === memberId && active ? "" : listLeadId;
                        updateCollaborativeListMeta(
                          selectedDefinition.id,
                          selectedDefinition.name,
                          { listMemberIds: nextMembers, listLeadId: nextLead },
                        );
                      }}
                      style={active ? goldButtonStyle : secondaryButtonStyle}
                    >
                      {member.name}
                    </button>
                  );
                })}
              </div>
            </div>
          </div>

          <div>
            <span style={fieldLabelStyle}>DEPARTMENTS</span>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 5 }}>
              {collaborativeDepartments.map((department) => {
                const active = listDepartmentIds.includes(department.id);
                return (
                  <button
                    key={department.id}
                    type="button"
                    onClick={() => {
                      const nextDepartments = active
                        ? listDepartmentIds.filter((id) => id !== department.id)
                        : [...listDepartmentIds, department.id];
                      updateCollaborativeListMeta(
                        selectedDefinition.id,
                        selectedDefinition.name,
                        { listDepartmentIds: nextDepartments },
                      );
                    }}
                    style={active ? goldButtonStyle : secondaryButtonStyle}
                  >
                    {department.label}
                  </button>
                );
              })}
            </div>
          </div>

          <small style={mutedSmallStyle}>
            Shared members can see this checklist in My Work. Individual items can still be assigned to different people or departments.
          </small>
        </div>
        <label style={{ display: "grid", gap: 5, marginTop: 12 }}>
          <span style={fieldLabelStyle}>LIST NOTES</span>
          <textarea
            value={listNotes}
            onChange={(event) => updateListNotes(event.currentTarget.value)}
            placeholder="Add instructions, reminders, vendor details, or notes for this list…"
            rows={3}
            style={{ ...inputStyle, resize: "vertical", lineHeight: 1.45 }}
          />
        </label>
        {listNotes ? (
          <div style={{ display: "flex", justifyContent: "flex-end", marginTop: 6 }}>
            <button
              type="button"
              onClick={() => {
                const updatedAt = new Date().toISOString();
                const listIds = new Set(listRecords.map((task) => String(task.id)));

                setTaskMeta((current) => {
                  const next = { ...current };
                  listIds.forEach((id) => {
                    next[id] = {
                      ...(current[id] || taskDetails(id)),
                      listId: selectedDefinition.id,
                      listName: selectedDefinition.name,
                      listNotes: "",
                      updatedAt,
                    } as AtlasTaskMeta;
                  });

                  try {
                    window.localStorage.setItem(
                      `atlas-task-meta-v1-${activePropertyId}`,
                      JSON.stringify(next),
                    );
                    if (activePropertyId === "2000") {
                      window.localStorage.setItem(
                        "atlas-task-meta-v1",
                        JSON.stringify(next),
                      );
                    }
                  } catch {}

                  return next;
                });

                listRecords.forEach((record) => {
                  const meta = taskDetails(record.id) as any;
                  const nextMeta = {
                    ...meta,
                    listId: selectedDefinition.id,
                    listName: selectedDefinition.name,
                    listNotes: "",
                    updatedAt,
                  };
                  void postAtlasRecord("tasks" as AtlasTable, {
                    ...record,
                    ...nextMeta,
                    taskMeta: nextMeta,
                    propertyId: activePropertyId,
                    updatedAt,
                  });
                });

                showSaveToast("List note deleted.");
              }}
              style={{ ...compactUtilityButtonStyle, color: colors.red }}
            >
              Delete Note
            </button>
          </div>
        ) : null}
      </section>
      <section style={{ ...cardStyle, padding: 10 }}>
        <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "minmax(0,1fr) auto", gap: 7, marginBottom: 9 }}><input value={newPartyChecklistItem} onChange={(event) => setNewPartyChecklistItem(event.currentTarget.value)} onKeyDown={(event) => { if (event.key === "Enter") addGraduationPartyChecklistItem(); }} placeholder="Add checklist item" style={inputStyle}/><button type="button" onClick={addGraduationPartyChecklistItem} style={goldButtonStyle}>Add</button></div>
        <div style={{ display: "grid", gap: 6 }}>
          {items.map((task) => {
            const meta = taskDetails(task.id) as any;
            const done = meta.status === "Completed";
            const assigneeIds = Array.isArray(meta.assigneeIds)
              ? meta.assigneeIds.map(String)
              : [];
            const departmentIds = Array.isArray(meta.departmentIds)
              ? meta.departmentIds.map(String)
              : [];
            const assigneeNames = assigneeIds
              .map((id: string) => listMemberLabel(id))
              .filter(Boolean);
            const departmentNames = departmentIds
              .map((id: string) => collaborativeDepartments.find((department) => department.id === id)?.label || id)
              .filter(Boolean);
            const assignmentSummary = [...assigneeNames, ...departmentNames].join(", ") || "Unassigned";

            return <div key={task.id} style={{ display: "grid", gap: 7, padding: "9px 10px", border: `1px solid ${colors.line}`, borderRadius: 10, background: done ? "#F0FAF5" : "#FFFFFF" }}>
              <div style={{ display: "grid", gridTemplateColumns: "auto minmax(0,1fr) auto auto", gap: 8, alignItems: "center" }}>
                <input type="checkbox" checked={done} aria-label={`Complete ${task.title}`} onChange={(event) => event.currentTarget.checked ? completeAtlasTask(task) : updateTaskDetails(task.id, { status: "Open", completedAt: undefined })}/>
                <div style={{ minWidth: 0 }}>
                  <span style={{ display: "block", color: colors.navy, fontWeight: 800, textDecoration: done ? "line-through" : "none", opacity: done ? .68 : 1 }}>{task.title}</span>
                  <small style={{ ...mutedSmallStyle, display: "block", marginTop: 2 }}>{assignmentSummary}</small>
                </div>
                <button
                  type="button"
                  onClick={() => keepChecklistItemAsWeeklyTask(task)}
                  style={compactUtilityButtonStyle}
                >
                  Keep Weekly
                </button>
                <button type="button" onClick={() => editChecklistItem(task)} style={compactUtilityButtonStyle}>Edit</button>
                <button type="button" aria-label={`Delete ${task.title}`} onClick={() => deleteAtlasTask(task.id)} style={{ ...compactUtilityButtonStyle, color: colors.red }}>Delete</button>
              </div>

              <details>
                <summary style={{ cursor: "pointer", color: colors.navy, fontWeight: 850, fontSize: 12 }}>
                  Assign
                </summary>
                <div style={{ display: "grid", gap: 8, marginTop: 7, padding: 9, borderRadius: 9, background: "#F8FAFC" }}>
                  <div>
                    <span style={fieldLabelStyle}>PEOPLE</span>
                    <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 5 }}>
                      {propertyTeamMembers.map((member) => {
                        const memberId = teamMemberKey(member);
                        const active = assigneeIds.includes(memberId);
                        return (
                          <button
                            key={memberId}
                            type="button"
                            onClick={() => {
                              const nextAssignees = active
                                ? assigneeIds.filter((id: string) => id !== memberId)
                                : [...assigneeIds, memberId];
                              setChecklistTaskAssignees(task, nextAssignees, departmentIds);
                            }}
                            style={active ? goldButtonStyle : secondaryButtonStyle}
                          >
                            {member.name}
                          </button>
                        );
                      })}
                    </div>
                  </div>

                  <div>
                    <span style={fieldLabelStyle}>DEPARTMENTS</span>
                    <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 5 }}>
                      {collaborativeDepartments.map((department) => {
                        const active = departmentIds.includes(department.id);
                        return (
                          <button
                            key={department.id}
                            type="button"
                            onClick={() => {
                              const nextDepartments = active
                                ? departmentIds.filter((id: string) => id !== department.id)
                                : [...departmentIds, department.id];
                              setChecklistTaskAssignees(task, assigneeIds, nextDepartments);
                            }}
                            style={active ? goldButtonStyle : secondaryButtonStyle}
                          >
                            {department.label}
                          </button>
                        );
                      })}
                    </div>
                  </div>
                </div>
              </details>
            </div>;
          })}
        </div>
      </section>
    </div>;
  }

  function renderOperationsIntelligence() {
    const today = todayISO();
    const blocked = workPlanTasks.filter((task) => taskDetails(task.id).status === "Blocked");
    const waiting = workPlanTasks.filter((task) => taskDetails(task.id).status === "Waiting");
    const routineCandidates = workPlanTasks.filter((task) => {
      const meta = taskDetails(task.id);
      const text = `${task.title} ${task.category}`.toLowerCase();
      const repeatable = ["clean", "check", "inspect", "mow", "edge", "water", "pool", "spa", "vehicle", "boat", "seadoo", "tool area", "walkway"].some((word) => text.includes(word));
      return meta.status === "Completed" && !task.recurring && repeatable;
    }).slice(0, 6);
    const seasonalAttention = seasonalItems.filter((item) => item.status !== "Completed" && item.windowStart <= addDays(today, 45) && item.deadline >= today);
    const vehiclesDue = vehicleCare.filter((vehicle) => vehicleDueScore(vehicle) >= 14).sort((a,b) => vehicleDueScore(b) - vehicleDueScore(a));
    return <div style={{ display: "grid", gap: 12 }}>
      <div style={noticeStyle}>Atlas surfaces patterns and risks, but nothing is added or rescheduled until you approve it.</div>
      <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "repeat(4,minmax(0,1fr))", gap: 8 }}>
        {[{ label: "Blocked", value: blocked.length, detail: "Needs your decision" }, { label: "Waiting", value: waiting.length, detail: "Follow-up may be due" }, { label: "Seasonal", value: seasonalAttention.length, detail: "Within 45 days" }, { label: "Vehicles", value: vehiclesDue.length, detail: "Onsite and becoming due" }].map((item) => <div key={item.label} style={cardStyle}><small style={fieldLabelStyle}>{item.label.toUpperCase()}</small><strong style={{ display: "block", marginTop: 4, fontSize: 24, color: colors.navy }}>{item.value}</strong><small style={mutedSmallStyle}>{item.detail}</small></div>)}
      </div>
      {routineCandidates.length ? <section style={cardStyle}><div style={eyebrowStyle}>Routine suggestions</div><h3 style={{ margin: "4px 0 10px", color: colors.navy }}>Completed work that may deserve a repeat</h3><div style={{ display: "grid", gap: 7 }}>{routineCandidates.map((task) => <div key={task.id} style={{ display: "grid", gridTemplateColumns: "minmax(0,1fr) auto", gap: 8, alignItems: "center", borderTop: `1px solid ${colors.line}`, paddingTop: 8 }}><span><strong style={{ display: "block" }}>{task.title}</strong><small style={mutedSmallStyle}>Completed {taskDetails(task.id).completedAt ? new Date(taskDetails(task.id).completedAt!).toLocaleDateString() : "recently"}</small></span><button type="button" onClick={() => makeSuggestedTaskRepeating(task)} style={secondaryButtonStyle}>Repeat weekly</button></div>)}</div></section> : <div style={noticeStyle}>No repeating-work suggestions yet. Atlas will surface completed cleaning, inspection, mowing, watering, pool, vehicle, and similar tasks here.</div>}
      {seasonalAttention.length ? <section style={cardStyle}><div style={eyebrowStyle}>Predictive reminders</div><div style={{ display: "grid", gap: 7, marginTop: 8 }}>{seasonalAttention.map((item) => <div key={item.id} style={{ display: "grid", gridTemplateColumns: "minmax(0,1fr) auto", gap: 8, alignItems: "center" }}><span><strong style={{ display: "block" }}>{item.title}</strong><small style={mutedSmallStyle}>Target {formatDate(item.targetDate)} · deadline {formatDate(item.deadline)}</small></span><button type="button" onClick={() => createSeasonalTask(item)} style={secondaryButtonStyle}>Schedule</button></div>)}</div></section> : null}
    </div>;
  }

  function renderBacklog() {
    return <div style={{ display: "grid", gap: 12 }}>
      <div style={{ ...cardStyle, display: "grid", gridTemplateColumns: isMobile ? "1fr" : "minmax(0,1fr) auto", gap: 8 }}><input value={newBacklogTitle} onChange={(event) => setNewBacklogTitle(event.currentTarget.value)} onKeyDown={(event) => { if (event.key === "Enter") addBacklogItem(); }} placeholder="Add an idea or someday item…" style={inputStyle}/><button type="button" onClick={addBacklogItem} style={goldButtonStyle}>Add to Backlog</button></div>
      <div style={{ display: "grid", gap: 8 }}>{backlogItems.map((item) => <div key={item.id} style={{ ...cardStyle, display: "grid", gridTemplateColumns: isMobile ? "1fr" : "minmax(0,1fr) auto", gap: 10, alignItems: "center" }}><div><strong>{item.title}</strong><small style={{ ...mutedSmallStyle, display: "block", marginTop: 4 }}>{item.category} · Not scheduled · Cannot become overdue</small></div><div style={{ display: "flex", gap: 7, flexWrap: "wrap" }}><button type="button" onClick={() => backlogToTask(item)} style={goldButtonStyle}>Make Task</button><button type="button" onClick={() => setBacklogItems((current) => current.filter((entry) => entry.id !== item.id))} style={{ ...secondaryButtonStyle, color: colors.red }}>Delete</button></div></div>)}{!backlogItems.length ? <div style={noticeStyle}>The Backlog is empty. Use it for ideas that should not have a due date yet.</div> : null}</div>
    </div>;
  }

  function renderVehicleCare() {
    const sorted = [...vehicleCare].sort((a, b) => vehicleDueScore(b) - vehicleDueScore(a));
    const selectedVehicle = vehicleCare.find((item) => item.id === selectedVehicleId) || sorted[0];
    const dueCount = vehicleCare.filter((item) => vehicleDueScore(item) >= Math.max(1, Number(item.cleaningIntervalDays || 14))).length;
    const onsiteCount = vehicleCare.filter((item) => item.onsite).length;
    const serviceDueCount = vehicleCare.filter((item) => item.nextServiceDate && item.nextServiceDate <= todayISO()).length;
    const vehicleTasks = selectedVehicle ? workPlanTasks.filter((task) => taskDetails(task.id).vehicleId === selectedVehicle.id || Boolean(selectedVehicle.assetId && taskDetails(task.id).assetId === selectedVehicle.assetId)) : [];
    const vehicleWorkOrders = selectedVehicle ? serviceRecords.filter((record) => Boolean(selectedVehicle.assetId && record.assetId === selectedVehicle.assetId) || record.notes?.includes(selectedVehicle.name)) : [];
    const vehicleDocuments = selectedVehicle ? intakeDocs.filter((document) => Boolean(selectedVehicle.assetId && (document.linkedAssetId === selectedVehicle.assetId || document.targetId === selectedVehicle.assetId)) || (document.targetName === selectedVehicle.name && document.targetType === "Asset")) : [];
    const vehiclePhotos = vehicleDocuments.flatMap((document) => document.files || []).filter((file) => String(file.type || "").startsWith("image/") || String(file.dataUrl || "").startsWith("data:image/"));

    const cleanStatus = (vehicle: AtlasVehicleCare) => {
      if (!vehicle.onsite) return { label: "Away", tone: "Offline" };
      if (!vehicle.lastCleaned) return { label: "No record", tone: "Open" };
      const interval = Math.max(1, Number(vehicle.cleaningIntervalDays || 14));
      const age = daysSince(vehicle.lastCleaned);
      if (age >= interval) return { label: `Due · ${age}d`, tone: "Open" };
      return { label: `Clean · ${age}d`, tone: "Completed" };
    };

    return <div style={{ display: "grid", gap: 12 }}>
      <div style={{ display: "grid", gridTemplateColumns: isMobile ? "repeat(2,minmax(0,1fr))" : "repeat(4,minmax(0,1fr))", gap: 8 }}>
        {[{ label: "Garage", value: vehicleCare.length }, { label: "Onsite", value: onsiteCount }, { label: "Cleaning due", value: dueCount }, { label: "Service due", value: serviceDueCount }].map((item) => <div key={item.label} style={{ ...cardStyle, padding: 10 }}><small style={fieldLabelStyle}>{item.label.toUpperCase()}</small><strong style={{ display: "block", marginTop: 3, fontSize: 23, color: colors.navy }}>{item.value}</strong></div>)}
      </div>

      <div style={{ ...cardStyle, padding: 10, display: "grid", gridTemplateColumns: isMobile ? "1fr" : "minmax(0,1fr) auto auto", gap: 8 }}>
        <input value={newVehicleName} onChange={(event) => setNewVehicleName(event.currentTarget.value)} onKeyDown={(event) => { if (event.key === "Enter") addFleetVehicle(); }} placeholder="Add car, vehicle, boat, or equipment…" style={inputStyle} />
        <button type="button" onClick={addFleetVehicle} style={goldButtonStyle}>Add</button>
        <button type="button" onClick={() => void setupGarageAndWaterCare()} disabled={fleetSetupState === "working" || waterCareSetupState === "working"} style={fleetSetupState === "ready" && waterCareSetupState === "ready" ? secondaryButtonStyle : goldButtonStyle}>{fleetSetupState === "working" || waterCareSetupState === "working" ? "Setting Up…" : fleetSetupState === "failed" || waterCareSetupState === "failed" ? "Retry Weekly Care" : fleetSetupState === "ready" && waterCareSetupState === "ready" ? "Weekly Care Ready ✓" : "Set Up Weekly Care"}</button>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "minmax(280px,36%) minmax(0,1fr)", gap: 12, alignItems: "start" }}>
        <section style={{ ...cardStyle, padding: 0, overflow: "hidden" }}>
          <div style={{ padding: "10px 12px", borderBottom: `1px solid ${colors.line}` }}><strong>Garage</strong><small style={{ ...mutedSmallStyle, display: "block", marginTop: 2 }}>Cars, vehicles, boats, cleaning, and service.</small></div>
          <div style={{ maxHeight: isMobile ? 460 : "72vh", overflowY: "auto" }}>
            {sorted.map((vehicle) => {
              const status = cleanStatus(vehicle);
              const selected = selectedVehicle?.id === vehicle.id;
              return <button key={vehicle.id} type="button" onClick={() => setSelectedVehicleId(vehicle.id)} style={{ width: "100%", border: 0, borderBottom: `1px solid ${colors.line}`, background: selected ? "#F3F7FC" : "#FFFFFF", padding: "10px 11px", textAlign: "left", cursor: "pointer", display: "grid", gap: 5 }}>
                <div style={{ display: "flex", justifyContent: "space-between", gap: 8, alignItems: "center" }}><strong style={{ color: colors.navy3 }}>{vehicle.name}</strong><span style={badgeStyle(status.tone)}>{status.label}</span></div>
                <small style={mutedSmallStyle}>{vehicle.kind || "Vehicle"} · {vehicle.onsite ? "Onsite" : "Away"}{vehicle.nextServiceDate ? ` · Service ${formatDate(vehicle.nextServiceDate)}` : ""}</small>
              </button>;
            })}
          </div>
        </section>

        {selectedVehicle ? <section style={{ ...cardStyle, position: isMobile ? "static" : "sticky", top: 88, maxHeight: isMobile ? "none" : "calc(100vh - 110px)", overflowY: isMobile ? "visible" : "auto" }}>
          <div style={{ display: "flex", justifyContent: "space-between", gap: 10, alignItems: "flex-start", marginBottom: 10 }}>
            <div><div style={eyebrowStyle}>Garage record</div><h3 style={{ margin: "3px 0 0", color: colors.navy }}>{selectedVehicle.name}</h3><small style={mutedSmallStyle}>{selectedVehicle.kind || "Vehicle"} · {selectedVehicle.onsite ? "Onsite" : "Away"}</small></div>
            <button type="button" onClick={() => { if (window.confirm(`Delete ${selectedVehicle.name}?`)) { setVehicleCare((current) => current.filter((item) => item.id !== selectedVehicle.id)); void deleteOperationalRecord("vehicle_care" as AtlasTable, selectedVehicle.id); setSelectedVehicleId(""); } }} style={{ ...secondaryButtonStyle, color: colors.red }}>Delete</button>
          </div>

          <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "repeat(2,minmax(0,1fr))", gap: 8 }}>
            <Field label="Name" value={selectedVehicle.name} onChange={(value) => updateVehicleCareRecord(selectedVehicle.id, { name: value })} />
            <SelectField label="Type" value={selectedVehicle.kind || "Vehicle"} onChange={(value) => updateVehicleCareRecord(selectedVehicle.id, { kind: value as AtlasVehicleCare["kind"] })} options={["Vehicle", "Boat", "Watercraft", "Equipment"]} />
            <SelectField label="Onsite" value={selectedVehicle.onsite ? "Yes" : "No"} onChange={(value) => updateVehicleCareRecord(selectedVehicle.id, { onsite: value === "Yes" })} options={["Yes", "No"]} />
            <SelectField label="Priority" value={selectedVehicle.priority} onChange={(value) => updateVehicleCareRecord(selectedVehicle.id, { priority: value as AtlasVehicleCare["priority"] })} options={["Normal", "High", "Skip"]} />
            <Field label="Last cleaned" type="date" value={selectedVehicle.lastCleaned} onChange={(value) => updateVehicleCareRecord(selectedVehicle.id, { lastCleaned: value })} />
            <Field label="Clean every (days)" type="number" value={String(selectedVehicle.cleaningIntervalDays || 14)} onChange={(value) => updateVehicleCareRecord(selectedVehicle.id, { cleaningIntervalDays: Math.max(1, Number(value || 14)) })} />
            <Field label="Last serviced" type="date" value={selectedVehicle.lastServiced || ""} onChange={(value) => updateVehicleCareRecord(selectedVehicle.id, { lastServiced: value })} />
            <Field label="Next service" type="date" value={selectedVehicle.nextServiceDate || ""} onChange={(value) => updateVehicleCareRecord(selectedVehicle.id, { nextServiceDate: value })} />
            <SelectField label="Assigned" value={selectedVehicle.assignedTo || "Nick"} onChange={(value) => updateVehicleCareRecord(selectedVehicle.id, { assignedTo: value as AtlasVehicleCare["assignedTo"] })} options={["Nick", "Addison", "Other", "Unassigned"]} />
            <SelectField
              label="Asset"
              value={assetRecords.find((asset) => asset.id === selectedVehicle.assetId)?.name || "Not linked"}
              onChange={(value) =>
                updateVehicleCareRecord(selectedVehicle.id, {
                  assetId:
                    value === "Not linked"
                      ? ""
                      : assetRecords.find((asset) => asset.name === value)?.id || "",
                })
              }
              options={["Not linked", ...assetRecords.map((asset) => asset.name)]}
            />
            <SelectField
              label="Location"
              value={locations.find((location) => location.id === selectedVehicle.locationId)?.name || "Not linked"}
              onChange={(value) =>
                updateVehicleCareRecord(selectedVehicle.id, {
                  locationId:
                    value === "Not linked"
                      ? ""
                      : locations.find((location) => location.name === value)?.id || "",
                })
              }
              options={["Not linked", ...locations.map((location) => location.name)]}
            />
          </div>

          <div style={{ marginTop: 8 }}><Field label="Notes" multiline value={selectedVehicle.notes} onChange={(value) => updateVehicleCareRecord(selectedVehicle.id, { notes: value })} /></div>

          <div style={{ display: "flex", gap: 7, flexWrap: "wrap", marginTop: 10 }}>
            <button type="button" disabled={!selectedVehicle.onsite} onClick={() => createVehicleCleaningTask(selectedVehicle)} style={goldButtonStyle}>Cleaning Task</button>
            <button type="button" onClick={() => markVehicleCleaned(selectedVehicle)} style={secondaryButtonStyle}>Mark Cleaned</button>
            <button type="button" onClick={() => markVehicleServiced(selectedVehicle)} style={secondaryButtonStyle}>Mark Serviced</button>
            <button type="button" onClick={() => addVehicleIssue(selectedVehicle)} style={secondaryButtonStyle}>Add Issue</button>
            <button type="button" onClick={() => createVehicleWorkOrder(selectedVehicle)} style={secondaryButtonStyle}>Work Order</button>
          </div>

          <section style={{ marginTop: 14, paddingTop: 12, borderTop: `1px solid ${colors.line}` }}>
            <div style={{ display: "flex", justifyContent: "space-between", gap: 10, alignItems: "center" }}><div><div style={eyebrowStyle}>Connected Records</div><strong>Vehicle relationships</strong></div>{selectedVehicle.assetId ? <button type="button" onClick={() => { setSelectedAssetId(selectedVehicle.assetId || ""); setScreen("assets"); }} style={secondaryButtonStyle}>Open Asset</button> : null}</div>
            <div style={{ display: "grid", gridTemplateColumns: isMobile ? "repeat(2,minmax(0,1fr))" : "repeat(4,minmax(0,1fr))", gap: 7, marginTop: 9 }}>{[["Tasks",vehicleTasks.length],["Work Orders",vehicleWorkOrders.length],["Photos",vehiclePhotos.length],["Documents",vehicleDocuments.length]].map(([label,value]) => <div key={String(label)} style={{ ...recordInfoItemStyle, minWidth: 0 }}><small style={fieldLabelStyle}>{label}</small><strong>{value}</strong></div>)}</div>
            <div style={{ display: "grid", gap: 7, marginTop: 10 }}>{vehicleTasks.map((task) => <button key={`vehicle-task-${task.id}`} type="button" onClick={() => { setSelectedTaskId(task.id); setTasksView("tasks"); setScreen("planner"); }} style={{ ...compactLinkedRowStyle, width: "100%" }}><span><strong>{task.title}</strong><small style={mutedSmallStyle}>Task · {taskDetails(task.id).status}</small></span><span>›</span></button>)}{vehicleWorkOrders.map((record) => <button key={`vehicle-work-${record.id}`} type="button" onClick={() => { setSelectedServiceId(record.id); setScreen("history"); }} style={{ ...compactLinkedRowStyle, width: "100%" }}><span><strong>{record.title}</strong><small style={mutedSmallStyle}>Work Order · {record.status}</small></span><span>›</span></button>)}{vehicleDocuments.map((document) => <button key={`vehicle-document-${document.id}`} type="button" onClick={() => { setSelectedDocumentId(document.id); setScreen("documents"); }} style={{ ...compactLinkedRowStyle, width: "100%" }}><span><strong>{document.title}</strong><small style={mutedSmallStyle}>{document.type || "Document"}</small></span><span>›</span></button>)}</div>
            {vehiclePhotos.length ? <div style={{ display: "flex", gap: 7, overflowX: "auto", marginTop: 10 }}>{vehiclePhotos.map((photo) => <button key={photo.id} type="button" onClick={() => setPreviewFile(photo)} style={{ border: `1px solid ${colors.line}`, borderRadius: 9, padding: 0, overflow: "hidden", background: "#FFFFFF", flex: "0 0 auto" }}><img src={photo.dataUrl || photo.url} alt={photo.name} style={{ width: 78, height: 60, objectFit: "cover", display: "block" }} /></button>)}</div> : null}
          </section>

          <section style={{ marginTop: 14, paddingTop: 12, borderTop: `1px solid ${colors.line}` }}>
            <div style={eyebrowStyle}>History</div>
            <div style={{ display: "grid", gap: 7, marginTop: 8 }}>
              {(selectedVehicle.history || []).slice(0, 12).map((entry) => <div key={entry.id} style={{ display: "grid", gridTemplateColumns: "auto minmax(0,1fr)", gap: 8, alignItems: "start" }}><span style={badgeStyle(entry.type === "Issue" ? "High" : entry.type === "Serviced" ? "Scheduled" : "Completed")}>{entry.type}</span><span><small style={{ display: "block", color: colors.text }}>{new Date(entry.date).toLocaleString()}</small>{entry.notes ? <small style={{ ...mutedSmallStyle, display: "block", marginTop: 2 }}>{entry.notes}</small> : null}</span></div>)}
              {!(selectedVehicle.history || []).length ? <div style={emptyStateStyle}>No Garage history recorded yet.</div> : null}
            </div>
          </section>
        </section> : <div style={emptyStateStyle}>Select a fleet record.</div>}
      </div>
    </div>;
  }

  function renderSeasonalWork() {
    const today = todayISO();
    const year = new Date().getFullYear();
    const seasonalCatalog: AtlasSeasonalItem[] = [
      { id: "winter-tires", title: "Winter tires", category: "Vehicles", season: "Fall", windowStart: `${year}-10-01`, targetDate: `${year}-11-01`, deadline: `${year}-11-30`, frequency: "Yearly", assignedTo: "Vendor", status: "Planned", notes: "Confirm which onsite vehicles need winter tires before scheduling." },
      { id: "annual-appliance-service", title: "Annual appliance service", category: "Appliances", season: "Fall", windowStart: `${year}-09-15`, targetDate: `${year}-10-15`, deadline: `${year}-12-15`, frequency: "Yearly", assignedTo: "Vendor", status: "Planned", notes: "Coordinate service before year end and retain service records." },
      { id: "irrigation-startup", title: "Irrigation startup and inspection", category: "Irrigation", season: "Spring", windowStart: `${year}-03-15`, targetDate: `${year}-04-15`, deadline: `${year}-05-01`, frequency: "Yearly", assignedTo: "Vendor", status: "Planned", notes: "Start controller, inspect all zones, and confirm backflow testing." },
      { id: "irrigation-winterization", title: "Irrigation winterization", category: "Irrigation", season: "Fall", windowStart: `${year}-09-15`, targetDate: `${year}-10-15`, deadline: `${year}-11-15`, frequency: "Yearly", assignedTo: "Vendor", status: "Planned", notes: "Schedule blowout, shutoff, backflow protection, and controller winter mode." },
      { id: "marine-opening", title: "Boat and Sea-Doo spring opening", category: "Marine", season: "Spring", windowStart: `${year}-03-15`, targetDate: `${year}-04-15`, deadline: `${year}-05-15`, frequency: "Yearly", assignedTo: "Vendor", status: "Planned", notes: "Inspect batteries, fluids, safety equipment, lifts, covers, and registrations." },
      { id: "marine-winterizing", title: "Boat and Sea-Doo winterizing", category: "Marine", season: "Fall", windowStart: `${year}-09-15`, targetDate: `${year}-10-15`, deadline: `${year}-11-15`, frequency: "Yearly", assignedTo: "Vendor", status: "Planned", notes: "Winterize watercraft, batteries, fuel, covers, and waterfront equipment." },
      { id: "spring-cleanup", title: "Spring property cleanup", category: "Grounds", season: "Spring", windowStart: `${year}-02-15`, targetDate: `${year}-03-15`, deadline: `${year}-04-15`, frequency: "Yearly", assignedTo: "Addison", status: "Planned", notes: "Grounds, drains, beds, furniture, walkways, dock approach, and outdoor reset." },
      { id: "owner-arrival-readiness", title: "Owner arrival readiness", category: "Arrivals", season: "Year-Round", windowStart: today, targetDate: addDays(today, 7), deadline: addDays(today, 10), frequency: "One-time", assignedTo: "Nick", status: "Planned", notes: "Set the real arrival date, then create the preparation plan." },
      { id: "party-event-readiness", title: "Party or event readiness", category: "Events", season: "Year-Round", windowStart: today, targetDate: addDays(today, 14), deadline: addDays(today, 14), frequency: "One-time", assignedTo: "Nick", status: "Planned", notes: "Set the event date and prepare guest areas, grounds, recreation, lighting, and final walkthrough." },
      { id: "annual-property-inspections", title: "Annual property inspections", category: "Inspections", season: "Fall", windowStart: `${year}-08-15`, targetDate: `${year}-09-15`, deadline: `${year}-11-01`, frequency: "Yearly", assignedTo: "Nick", status: "Planned", notes: "Review roof, drainage, exterior, mechanical, safety, dock, and major assets." },
    ];
    const missingPrograms = seasonalCatalog.filter((program) => !seasonalItems.some((item) => item.id === program.id));
    const daysUntil = (date: string) => Math.ceil((new Date(`${date}T12:00:00`).getTime() - new Date(`${today}T12:00:00`).getTime()) / 86400000);
    const completeSeasonal = (item: AtlasSeasonalItem) => {
      const completedAt = new Date().toISOString();
      setSeasonalItems((current) => current.map((entry) => {
        if (entry.id !== item.id) return entry;
        if (entry.frequency !== "Yearly") return { ...entry, status: "Completed", lastCompletedAt: completedAt, completionHistory: [...(entry.completionHistory || []), completedAt] };
        const shiftYear = (date: string) => date ? `${Number(date.slice(0, 4)) + 1}${date.slice(4)}` : date;
        return { ...entry, status: "Planned", windowStart: shiftYear(entry.windowStart), targetDate: shiftYear(entry.targetDate), deadline: shiftYear(entry.deadline), lastCompletedAt: completedAt, completionHistory: [...(entry.completionHistory || []), completedAt] };
      }));
      showSaveToast(item.frequency === "Yearly" ? `${item.title} completed and rolled forward one year.` : `${item.title} completed.`);
    };
    const active = seasonalItems.filter((item) => item.status !== "Completed");
    const overdue = active.filter((item) => item.deadline < today);
    const inWindow = active.filter((item) => item.windowStart <= today && item.deadline >= today);
    const upcoming = active.filter((item) => item.windowStart > today && daysUntil(item.windowStart) <= 60);
    const card = (item: AtlasSeasonalItem) => {
      const isOverdue = item.status !== "Completed" && item.deadline < today;
      const open = item.status !== "Completed" && item.windowStart <= today && item.deadline >= today;
      return <article key={item.id} style={{ ...cardStyle, borderColor: isOverdue ? "#E79A9A" : open ? colors.gold : colors.line }}><div style={{ display: "flex", justifyContent: "space-between", gap: 10, flexWrap: "wrap" }}><div><small style={fieldLabelStyle}>{item.category || "SEASONAL"}</small><strong style={{ display: "block", marginTop: 3, color: colors.navy }}>{item.title}</strong><small style={{ ...mutedSmallStyle, display: "block", marginTop: 4 }}>{item.frequency} · {item.season} · Target {formatDate(item.targetDate)}</small></div><span style={badgeStyle(isOverdue ? "High" : open ? "Open" : item.status === "Completed" ? "Completed" : "Scheduled")}>{isOverdue ? "Overdue" : open && item.status === "Planned" ? "Ready to schedule" : item.status}</span></div><p style={{ ...mutedSmallStyle, margin: "9px 0" }}>{item.notes}</p><div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "repeat(3,minmax(0,1fr))", gap: 8 }}><Field label="Window opens" type="date" value={item.windowStart} onChange={(value) => setSeasonalItems((current) => current.map((entry) => entry.id === item.id ? { ...entry, windowStart: value } : entry))}/><Field label="Target" type="date" value={item.targetDate} onChange={(value) => setSeasonalItems((current) => current.map((entry) => entry.id === item.id ? { ...entry, targetDate: value } : entry))}/><Field label="Deadline" type="date" value={item.deadline} onChange={(value) => setSeasonalItems((current) => current.map((entry) => entry.id === item.id ? { ...entry, deadline: value } : entry))}/></div><div style={{ display: "flex", gap: 7, flexWrap: "wrap", marginTop: 10 }}><button type="button" onClick={() => createSeasonalTask(item)} style={goldButtonStyle}>Schedule Work</button><button type="button" onClick={() => completeSeasonal(item)} style={secondaryButtonStyle}>Complete</button></div>{item.lastCompletedAt ? <small style={{ ...mutedSmallStyle, display: "block", marginTop: 8 }}>Last completed {new Date(item.lastCompletedAt).toLocaleDateString()}</small> : null}</article>;
    };
    return <div style={{ display: "grid", gap: 12 }}><section style={{ ...cardStyle, background: colors.navy, color: "#FFFFFF" }}><div style={{ display: "flex", justifyContent: "space-between", gap: 14, flexWrap: "wrap" }}><div><div style={{ ...eyebrowStyle, color: colors.gold2 }}>Seasonal Intelligence</div><h2 style={{ margin: "4px 0", color: "#FFFFFF" }}>Plan the work before it becomes urgent</h2><p style={{ margin: 0, opacity: .84 }}>Atlas watches scheduling windows, targets, deadlines, and yearly completion history.</p></div><div style={{ textAlign: "right" }}><strong style={{ display: "block", fontSize: 25 }}>{inWindow.length}</strong><small style={{ opacity: .82 }}>ready to schedule</small></div></div></section><div style={{ display: "grid", gridTemplateColumns: isMobile ? "repeat(2,minmax(0,1fr))" : "repeat(4,minmax(0,1fr))", gap: 8 }}>{[["Overdue",overdue.length],["In window",inWindow.length],["Next 60 days",upcoming.length],["Programs",seasonalItems.length]].map(([label,value]) => <div key={String(label)} style={{ ...cardStyle, padding: 10 }}><small style={fieldLabelStyle}>{String(label).toUpperCase()}</small><strong style={{ display: "block", marginTop: 3, fontSize: 22, color: label === "Overdue" && Number(value) ? colors.red : colors.navy }}>{value}</strong></div>)}</div>{missingPrograms.length ? <section style={cardStyle}><div style={eyebrowStyle}>Recommended programs</div><div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "repeat(2,minmax(0,1fr))", gap: 8, marginTop: 9 }}>{missingPrograms.map((program) => <button key={program.id} type="button" onClick={() => { setSeasonalItems((current) => [...current, program]); showSaveToast(`${program.title} added.`); }} style={{ ...secondaryButtonStyle, minHeight: 55, textAlign: "left", justifyContent: "space-between" }}><span><strong style={{ display: "block" }}>{program.title}</strong><small style={mutedSmallStyle}>{program.category} · {program.season}</small></span><span>＋</span></button>)}</div></section> : null}<section><div style={{ ...eyebrowStyle, marginBottom: 8 }}>Seasonal plan</div><div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "repeat(2,minmax(0,1fr))", gap: 10 }}>{seasonalItems.sort((a, b) => a.windowStart.localeCompare(b.windowStart)).map(card)}</div></section></div>;
  }

  async function submitAddisonFieldReport(report: {
    description: string;
    locationId: string;
    canHandle: boolean;
    files: UploadedFileRecord[];
  }) {
    const description = report.description.trim();
    if (!description) return { ok: false, error: "Describe what you found." };
    const titleLine = description.split(/\r?\n/).find((line) => line.trim())?.trim() || "Field Report";
    const title = titleLine.length > 80 ? `${titleLine.slice(0, 77)}…` : titleLine;
    const reportLocationName = report.locationId
      ? locationName(report.locationId)
      : "General property";

    const matchingOpenReport = inboxItems.some((item) => {
      if (item.status === "Archived") return false;
      const data = (item.extractedData || {}) as Record<string, unknown>;
      return (
        item.source === "Addison Field Report" &&
        String(data.propertyId || "") === activePropertyId &&
        String(item.notes || "").trim().toLowerCase() ===
          description.toLowerCase() &&
        String(data.locationId || item.targetId || "") === report.locationId
      );
    });
    if (matchingOpenReport) {
      showSaveToast("This report is already waiting in the Inbox.");
      return { ok: true };
    }

    try {
      const response = await fetch("/api/atlas-inbox", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          title,
          intakeType: "Work Order Issue",
          status: "Needs Review",
          source: "Addison Field Report",
          notes: description,
          pastedText: "",
          files: report.files,
          targetType: report.locationId ? "Location" : "General",
          targetId: report.locationId,
          targetName: reportLocationName,
          proposedAction: "Attach to Existing",
          extractedData: {
            propertyId: activePropertyId,
            reportType: "Field Report",
            submittedBy: currentAtlasUser?.name || "Addison",
            canHandle: report.canHandle,
            locationId: report.locationId,
            locationName: reportLocationName,
            suggestedAction: "Create Task",
          },
        }),
      });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok || payload?.ok === false) {
        throw new Error(payload?.error || "Field Report could not be sent.");
      }
      const saved = payload.item as InboxItemRecord;
      setInboxItems((current) => [
        saved,
        ...current.filter((item) => item.id !== saved.id),
      ]);
      showSaveToast("Report sent to Inbox.");
      return { ok: true };
    } catch (error) {
      const message = error instanceof Error ? error.message : "Field Report could not be sent.";
      showSaveToast(message, "warning");
      return { ok: false, error: message };
    }
  }

